"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[48994],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},83113:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"In Erinnerung an Bob Lee","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/de/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6. April 2023","top_news":"In Erinnerung an Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/de/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/de/2023/04/05"}}');var t=i(23420),s=i(3331);const a={localized_date:"6. April 2023",top_news:"In Erinnerung an Bob Lee"},d="2023-04-06",u={},l=[{value:"In Erinnerung an Bob Lee",id:"in-erinnerung-an-bob-lee",level:2},{value:"Bob Lee, ehemaliger CTO von Square, ist nach einer Messerstecherei in San Francisco gestorben",id:"bob-lee-ehemaliger-cto-von-square-ist-nach-einer-messerstecherei-in-san-francisco-gestorben",level:2},{value:"Informieren Sie Mit iOS k\xf6nnen Netzbetreiber WiFi-Netzwerke hinzuf\xfcgen, die Sie nicht abschalten k\xf6nnen",id:"informieren-sie-mit-ios-k\xf6nnen-netzbetreiber-wifi-netzwerke-hinzuf\xfcgen-die-sie-nicht-abschalten-k\xf6nnen",level:2},{value:"Deep Learning: Grundlagen f\xfcr eine stabile Verbreitung",id:"deep-learning-grundlagen-f\xfcr-eine-stabile-verbreitung",level:2},{value:"CAN Injection: Schl\xfcsselloser Autodiebstahl",id:"can-injection-schl\xfcsselloser-autodiebstahl",level:2},{value:"Firefox-Ingenieure entdecken einen Windows Defender-Bug, der eine hohe CPU-Auslastung verursacht",id:"firefox-ingenieure-entdecken-einen-windows-defender-bug-der-eine-hohe-cpu-auslastung-verursacht",level:2},{value:"Segment Anything Model (SAM) kann jedes Objekt in einem Bild &quot;ausschneiden&quot;.",id:"segment-anything-model-sam-kann-jedes-objekt-in-einem-bild-ausschneiden",level:2},{value:"Das Bitcoin-Whitepaper ist in jeder Kopie von macOS versteckt.",id:"das-bitcoin-whitepaper-ist-in-jeder-kopie-von-macos-versteckt",level:2},{value:"Ehemaliger Square CTO Bob Lee in der Innenstadt von San Francisco erstochen",id:"ehemaliger-square-cto-bob-lee-in-der-innenstadt-von-san-francisco-erstochen",level:2},{value:"Ein Pl\xe4doyer f\xfcr das Verbot von Kindern in sozialen Medien",id:"ein-pl\xe4doyer-f\xfcr-das-verbot-von-kindern-in-sozialen-medien",level:2},{value:"Dang wird bald 65.535 Karmapunkte haben",id:"dang-wird-bald-65535-karmapunkte-haben",level:2},{value:"Neuronale Netze: Von Null auf Held",id:"neuronale-netze-von-null-auf-held",level:2},{value:"Ein Trick, um den Fluss zu erreichen: Lassen Sie Ihre Arbeit kaputt gehen",id:"ein-trick-um-den-fluss-zu-erreichen-lassen-sie-ihre-arbeit-kaputt-gehen",level:2},{value:"Wird der Arbeitsspeicher vor der Verwendung in einem anderen LXC-Container geleert?",id:"wird-der-arbeitsspeicher-vor-der-verwendung-in-einem-anderen-lxc-container-geleert",level:2},{value:"Perspektive: Open Source WebAssembly-gest\xfctzte BI",id:"perspektive-open-source-webassembly-gest\xfctzte-bi",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - Die Clickbait-Schlagzeilen-Programmiersprache",id:"tabloid---die-clickbait-schlagzeilen-programmiersprache",level:2},{value:"GPT4 simuliert einen FTP-Server auf ftp.disney.com",id:"gpt4-simuliert-einen-ftp-server-auf-ftpdisneycom",level:2},{value:"mmap verwenden, um LLaMA schneller laden zu lassen",id:"mmap-verwenden-um-llama-schneller-laden-zu-lassen",level:2}];function h(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,t.jsx)(n.h2,{id:"in-erinnerung-an-bob-lee",children:"In Erinnerung an Bob Lee"}),"\n",(0,t.jsx)(n.p,{children:"Die Tech-Community trauert um Bob Lee, eine bekannte Pers\xf6nlichkeit der Branche. Lee war ein Verfechter von Java, arbeitete bei Google und Square und war bekannt f\xfcr seine Arbeit am Guice Dependency Injection Framework. Au\xdferdem war er Mitbegr\xfcnder der Android Alliance, einer Initiative zur F\xf6rderung von Innovationen im Android-\xd6kosystem. Lees Beitr\xe4ge zur Tech-Welt waren weithin anerkannt, und er wird von seinen Kollegen und Kollegen sehr vermisst werden. Viele haben in den sozialen Medien ihr Beileid bekundet und Lee als Mentor und Freund in Erinnerung behalten, der sich immer Zeit f\xfcr andere nahm. Ruhe in Frieden, Bob Lee."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, der Mitautor von Guice und Java-Bibliotheken, der f\xfcr seine technischen F\xe4higkeiten, seine Freundlichkeit und Bescheidenheit bekannt war, ist verstorben. Sein Tod hat die Tech-Community in Trauer versetzt und viele Menschen dazu veranlasst, ihre Erinnerungen und Anekdoten \xfcber ihn zu teilen. Lees Verm\xe4chtnis an Innovation und Leidenschaft hat viele inspiriert, und seine Beitr\xe4ge zur Branche werden uns fehlen. W\xe4hrend einige Kommentare abschweiften, teilten die meisten positive Gedanken und Erfahrungen \xfcber Bob."]}),"\n",(0,t.jsx)(n.h2,{id:"bob-lee-ehemaliger-cto-von-square-ist-nach-einer-messerstecherei-in-san-francisco-gestorben",children:"Bob Lee, ehemaliger CTO von Square, ist nach einer Messerstecherei in San Francisco gestorben"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, der Erfinder der Cash App und Chief Technology Officer bei Square, wurde als der Mann identifiziert, der in San Francisco durch eine Messerstecherei get\xf6tet wurde. Die Polizei hat noch keine Festnahmen vorgenommen und keine Informationen \xfcber m\xf6gliche Verd\xe4chtige ver\xf6ffentlicht. Lee war 43 Jahre alt, war der Gr\xfcnder von Cash App und arbeitete zum Zeitpunkt seines Todes als Chief Product Officer bei MobileCoin."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nDer Tod des ehemaligen CTO von Square, Bob Lee, in San Francisco l\xf6st eine Diskussion \xfcber Kriminalit\xe4t und Regierungsf\xfchrung aus. Die Kommentare umfassen Wohlstandsgef\xe4lle, Obdachlosigkeit, Gentrifizierung und m\xf6gliche L\xf6sungen. Die Diskussion wirft Fragen zu politischen Systemen und unzuverl\xe4ssigen Kriminalit\xe4tsstatistiken in US-St\xe4dten auf. Die Nutzer er\xf6rtern m\xf6gliche Ursachen der Kriminalit\xe4t wie Massenmigration, Wohlstandsgef\xe4lle, beeintr\xe4chtigte Justizsysteme und mangelnde Reaktionsf\xe4higkeit der Polizei. Ein Vergleich der Kriminalit\xe4t zwischen verschiedenen L\xe4ndern oder Kulturen ist nicht hilfreich. Das Problem der Kriminalit\xe4t ist komplex und nicht das Ergebnis eines einzelnen Faktors."]}),"\n",(0,t.jsx)(n.h2,{id:"informieren-sie-mit-ios-k\xf6nnen-netzbetreiber-wifi-netzwerke-hinzuf\xfcgen-die-sie-nicht-abschalten-k\xf6nnen",children:"Informieren Sie Mit iOS k\xf6nnen Netzbetreiber WiFi-Netzwerke hinzuf\xfcgen, die Sie nicht abschalten k\xf6nnen"}),"\n",(0,t.jsx)(n.p,{children:'Das iOS-Betriebssystem erlaubt es den Betreibern, WiFi-Netzwerke hinzuzuf\xfcgen, denen die Nutzer nicht widersprechen k\xf6nnen. Diese Funktion sorgt bei iPhone-Nutzern mit begrenzten Datentarifen oder Datenschutzbedenken f\xfcr Unruhe. Die Funktion soll den Betreibern helfen, WiFi-Hotspots einzurichten, aber sie erm\xf6glicht es ihnen auch, \xf6ffentliche WiFi-Netzwerke hinzuzuf\xfcgen, mit denen sich die Nutzer unwissentlich verbinden und so m\xf6glicherweise sensible Daten sammeln k\xf6nnen. Die Nutzer haben nur begrenzte M\xf6glichkeiten, die Funktion zu deaktivieren, einschlie\xdflich der M\xf6glichkeit, WiFi komplett zu deaktivieren oder die Option "Dieses Netzwerk vergessen" auszuw\xe4hlen, wenn sie es sehen. Einige Nutzer fordern von Apple mehr Kontrolle \xfcber diese Funktion, w\xe4hrend andere die Verwendung eines VPN vorschlagen, um ihre Daten zu sch\xfctzen.'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 erlaubt es Netzbetreibern, verwaltete Netzwerke zu Ger\xe4ten hinzuzuf\xfcgen, die Mobilfunkkosten zu senken und die Deaktivierung von Auto-Join zu verhindern, wobei es derzeit keine M\xf6glichkeit gibt, diese Netzwerke zu entfernen, au\xdfer die Netzwerkeinstellungen zur\xfcckzusetzen. Nutzer berichten, dass T-Mobile Daten stiehlt und Wingman-Netzwerke w\xe4hrend des Fluges nicht ausgeschaltet werden. Sie sind schockiert dar\xfcber, dass Betreiber WiFi-Verbindungen diktieren, ohne dass der Nutzer dagegen vorgehen kann. Es wird diskutiert, wie man die vollst\xe4ndige Kontrolle \xfcber das Ger\xe4t erlangen kann, wobei einige Nutzer GrapheneOS f\xfcr Sicherheitsupdates empfehlen. Die WiFi-Hotspots der Betreiber werden daf\xfcr kritisiert, dass sie die Verbindungen zu lokalen Ger\xe4ten unterbrechen, und einige finden die Funktion in \xfcberf\xfcllten Gebieten n\xfctzlich."]}),"\n",(0,t.jsx)(n.h2,{id:"deep-learning-grundlagen-f\xfcr-eine-stabile-verbreitung",children:"Deep Learning: Grundlagen f\xfcr eine stabile Verbreitung"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" ist ein Kurs mit \xfcber 30 Stunden Videoinhalten, der den Stable-Diffusion-Algorithmus von Grund auf behandelt und eng mit Experten von Stable.ai und Hugging Face zusammenarbeitet. Der Kurs bietet eine rigorose Abdeckung der neuesten Techniken und geht sogar \xfcber das hinaus, was Stable Diffusion beinhaltet, was ihn aus vielen Gr\xfcnden zu einem gro\xdfartigen Lernziel macht. Um jedoch das meiste aus diesem Kurs herauszuholen, sollten Sie ein einigerma\xdfen sicherer Deep Learning-Praktiker sein. W\xe4hrend des Kurses werden wir Diffusionsmethoden erforschen, unsere eigenen Modelle von Grund auf implementieren, Python-Konzepte beherrschen und PyTorch zur Implementierung unserer Modelle einsetzen. Wir werden die Grundlagen der Diffusion, Deep-Learning-Optimierer, Python-Konzepte, Grundlagen, Pseudo-Zufallszahlengenerierung, Architekturen neuronaler Netze, generative Architekturen, Transformatoren und gemischtes Pr\xe4zisionstraining behandeln.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),'.\nDer Kurs "Deep Learning Foundations to Stable Diffusion" erforscht moderne generative Modellierung, w\xe4hrend einige empfehlen, sich auf Marketing zu konzentrieren. Der Deep-Learning-Kurs von Fast.ai schafft ein Programmier-Framework von Grund auf und wird jedem empfohlen, der sich f\xfcr dieses Thema interessiert. Es gibt eine Debatte \xfcber die potenziellen Gefahren fortgeschrittener KI und die Bedeutung von Regulierung und ethischen \xdcberlegungen. Kommentatoren schlagen vor, KI-Ausgaben zu verbieten, aber das ist keine langfristige L\xf6sung, solange nicht alle L\xe4nder dies tun. Der FastAI-Kurs enth\xe4lt keine politisch oder religi\xf6s voreingenommenen Aussagen, und sein Inhalt gilt als erstklassig. Der Kurs ist f\xfcr jeden zug\xe4nglich, der \xfcber mathematische Grundkenntnisse verf\xfcgt, und deckt fortgeschrittene Konzepte ab.']}),"\n",(0,t.jsx)(n.h2,{id:"can-injection-schl\xfcsselloser-autodiebstahl",children:"CAN Injection: Schl\xfcsselloser Autodiebstahl"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nAutodiebe nutzen eine neue Technik namens CAN Injection, um intelligente Schl\xfcsselsysteme in modernen Autos zu umgehen, indem sie Schwachstellen im CAN-Bus-Kommunikationsprotokoll ausnutzen. Hochentwickelte Sicherheitssysteme f\xfcr Autos, einschlie\xdflich Wegfahrsperren, sind anf\xe4llig geworden. Diebe verwenden ein Ger\xe4t namens CAN Injector, um Autos ohne Schl\xfcssel zu stehlen, indem sie gef\xe4lschte Nachrichten in das interne Kommunikationssystem des Autos einspeisen. Das Ger\xe4t kostet 10 Dollar und enth\xe4lt einen PIC18F-Chip, vorprogrammierte Firmware, einen Transceiver und einen zus\xe4tzlichen Schaltkreis. Der CAN Injector kann durch eine schnelle L\xf6sung oder eine kryptografische Nachrichten\xfcbermittlung ausgeschaltet werden. Ian Haken zeigt mehrere M\xf6glichkeiten auf, wie Automobilhersteller die Sicherheit von Fahrzeugen verbessern k\xf6nnen, doch die kriminelle Ausnutzung dieser Technik ist weit verbreitet. Es handelt sich um ein branchenweites Problem, das eine Aktualisierung der Steuerger\xe4tesoftware erfordert, um Dieben das Handwerk zu legen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nEine Technik zum Diebstahl schl\xfcsselloser Autos, bekannt als CAN Injection, wurde auf Hacker News hervorgehoben. Verbraucher sollten sich davor h\xfcten, den CAN-Bus zu verschl\xfcsseln oder zu signieren, da dies Diagnosetools von Drittanbietern einschr\xe4nken und die Reparaturkosten erh\xf6hen kann. Der CAN-Bus steuert mehrere Fahrzeugfunktionen, und die Fahrzeughersteller optimieren die Kosten r\xfccksichtslos. Die Automobilhersteller sind gesetzlich verpflichtet, sich von den H\xe4ndlern zu trennen, aber einige Kommentare kritisieren, dass sie sich an den Geist des Gesetzes halten. Premium-Automarken setzen verschiedene Sicherheitsma\xdfnahmen ein, um das Hacken von Fahrzeugen zu verhindern, darunter Wegfahrsperren mit geeigneten kryptografischen Protokollen zur Authentifizierung von Startfreigaben und signierte CAN/FlexRay/Ethernet-Frames zur Verhinderung von Nachrichtenf\xe4lschungen. Billige Autos sind das Ziel, da sie leicht zu stehlen sind, w\xe4hrend teure Autos das Ziel eines gewaltsamen Diebstahls sind. Die in dem Artikel beschriebene Schwachstelle k\xf6nnte auf fast jedes nicht angeschlossene Fahrzeug angewandt werden, das in den letzten zehn Jahren hergestellt wurde. Die Verwendung des CAN-Busses in kritischen Systemen, wie z. B. in der Luftfahrt und in der Automobilindustrie, ist auf seine einfache Verdrahtung und Kosteneffizienz zur\xfcckzuf\xfchren."]}),"\n",(0,t.jsx)(n.h2,{id:"firefox-ingenieure-entdecken-einen-windows-defender-bug-der-eine-hohe-cpu-auslastung-verursacht",children:"Firefox-Ingenieure entdecken einen Windows Defender-Bug, der eine hohe CPU-Auslastung verursacht"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Dieser Text steht nicht im Zusammenhang mit dem Thema)."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nFirefox-Ingenieure haben einen Fehler in Windows Defender gefunden, der die CPU-Auslastung von Mozillas Browser verursacht. Microsoft ver\xf6ffentlicht einen Patch, um dies zu beheben. Andere AV-Produkte k\xf6nnten ebenfalls Probleme mit der CPU-Auslastung verursachen. Firefox macht aus Sicherheitsgr\xfcnden mehr Systemaufrufe als Chrome. Ein Vergleich zeigt, dass Firefox in einigen Tests schneller arbeitet als Chrome. Experten diskutieren die Grenzen von Defender und schlagen Sandboxing und Hardware-MFA vor. Nutzer diskutieren \xfcber die Effektivit\xe4t von Defender im Vergleich zu AV-Software von Drittanbietern. Einige Nutzer berichten von Problemen mit dem Defender, die einen langsamen Dateisystemzugriff verursachen."]}),"\n",(0,t.jsx)(n.h2,{id:"segment-anything-model-sam-kann-jedes-objekt-in-einem-bild-ausschneiden",children:'Segment Anything Model (SAM) kann jedes Objekt in einem Bild "ausschneiden".'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://segment-anything.com/",children:"Original"}),".\nDas von Meta AI entwickelte Segment Anything Model (SAM) kann jedes beliebige Objekt in einem Bild mit hoher Genauigkeit isolieren. Es kann Objekte erfolgreich identifizieren und segmentieren, selbst wenn sie nur teilweise sichtbar oder verdeckt sind. SAM verbessert fr\xfchere Modelle, die sich auf Ortsangaben oder hervorstechende Objekte st\xfctzen. Anstatt diese Hinweise zu verwenden, wendet SAM Meta-Lernen an, indem es den Lernprozess eines bestehenden Modells nutzt, um kleine, verzerrte Datens\xe4tze oder ungesehene Objekte zu erkennen. SAM kann sowohl f\xfcr praktische Anwendungen wie die Bildbearbeitung als auch f\xfcr die Forschung auf dem Gebiet des Computersehens eingesetzt werden."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nSAM von Meta AI erm\xf6glicht die Erzeugung von Masken in Echtzeit, um beliebige Objekte aus einem Bild "auszuschneiden". Die Lizenzierung und die beeindruckenden Inferenzf\xe4higkeiten des Modells k\xf6nnten es bei Technikexperten beliebt machen. Zu den Problemen geh\xf6ren die langsamere Geschwindigkeit mit dem RTX 2080ti 11GB Modell und die begrenzte Pr\xe4zision bei transparenten Objekten. Einige sehen die Ver\xf6ffentlichungsstrategie von Meta AI als Teil einer AR-Adoptionsoffensive. Nutzer loben die Kostenreduzierung von SAM bei der Datenkommentierung, kritisieren aber die Geschwindigkeit und vergleichen sie mit iOS. Die Entwicklung k\xf6nnte auch potenzielle Sicherheitskamera-Anwendungen und AdobeAI-Integration haben.']}),"\n",(0,t.jsx)(n.h2,{id:"das-bitcoin-whitepaper-ist-in-jeder-kopie-von-macos-versteckt",children:"Das Bitcoin-Whitepaper ist in jeder Kopie von macOS versteckt."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nEine PDF-Kopie von Satoshi Nakamotos Bitcoin-Whitepaper wurde in jeder modernen Kopie von macOS seit Mojave 2018 entdeckt und kann \xfcber ein Beispieldokument im Dienstprogramm Image Capture aufgerufen werden. Das Whitepaper wird als Beispieldokument f\xfcr ein Ger\xe4t namens "Virtual Scanner II" verwendet, das entweder versteckt oder standardm\xe4\xdfig nicht f\xfcr alle installiert ist. Der Grund f\xfcr die Einbindung des Whitepapers ist noch unklar, es k\xf6nnte sich jedoch um ein praktisches und leichtgewichtiges mehrseitiges PDF-Dokument zu Testzwecken handeln. Im Internet gibt es nur wenige Informationen \xfcber Virtual Scanner II oder die Aufnahme des Whitepapers in macOS.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nDas Bitcoin-Whitepaper ist seit 2019 in jeder macOS-Kopie versteckt; es wird spekuliert, warum es enthalten ist, und Nutzer warnen vor Mining auf iPhones. Die Hash-Summe stimmt mit der Originalversion \xfcberein, aber es gibt verschiedene Theorien dar\xfcber, warum es enthalten ist. Es gab Beschwerden \xfcber die Unterst\xfctzung eines Ponzi-Schemas, aber Nutzer stellen klar, dass es versteckt ist. Apple mag es aus Bequemlichkeit eingef\xfcgt haben, aber der Beitrag regt den Dialog \xfcber die Auswirkungen von Bitcoin an. Nutzer kommentieren das in einem Artikel verwendete Bild, die Gr\xf6\xdfe der PDF-Datei und die Tatsache, dass die Technik ihren k\xfcnstlerischen Spa\xdf verliert."]}),"\n",(0,t.jsx)(n.h2,{id:"ehemaliger-square-cto-bob-lee-in-der-innenstadt-von-san-francisco-erstochen",children:"Ehemaliger Square CTO Bob Lee in der Innenstadt von San Francisco erstochen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nDer ehemalige Square CTO Bob Lee wurde laut The Standard in der Innenstadt von San Francisco erstochen. Lee war Chief Product Officer von MobileCoin, einem Krypto-Unternehmen in San Francisco, und ein beliebtes Mitglied der Software-Entwicklungs- und Technologie-Communities in der Bay Area. Die SFPD hat keine weiteren Details oder die Identit\xe4t des Opfers bekannt gegeben und bittet um Augenzeugenberichte und Videomaterial f\xfcr ihre Ermittlungen. Bis zum 2. April gab es in San Francisco 12 Morde, zwei mehr als im gleichen Zeitraum des Vorjahres. Der Standard berichtet \xfcber wichtige Themen, einschlie\xdflich der Strafjustiz in San Francisco, und bietet Newsletter und einen umfassenden \xdcberblick \xfcber Politik und Kultur in San Francisco."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nEhemaliger Square CTO Bob Lee in San Francisco erstochen; Kommentare beziehen sich auf neue Details."]}),"\n",(0,t.jsx)(n.h2,{id:"ein-pl\xe4doyer-f\xfcr-das-verbot-von-kindern-in-sozialen-medien",children:"Ein Pl\xe4doyer f\xfcr das Verbot von Kindern in sozialen Medien"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nDie Debatte \xfcber das Verbot sozialer Medien f\xfcr Kinder ist aufgrund von Bedenken \xfcber Sucht und Negativit\xe4t im Gange. Es wurden bereits einige Gesetze verabschiedet, die den Zugang von Minderj\xe4hrigen zu Social-Media-Seiten einschr\xe4nken und s\xfcchtig machende Funktionen entfernen sollen, was jedoch Auswirkungen auf die b\xfcrgerlichen Freiheiten hat und den Zugang zu Nachrichten und anderen Perspektiven einschr\xe4nkt. Zwar haben Gerichte Online-Schutzma\xdfnahmen f\xfcr die Sicherheit von Kindern f\xfcr ung\xfcltig erkl\xe4rt, doch die Schaffung von Anti-Sucht-Botschaften und rechtlichen Beschr\xe4nkungen kann zu Konflikten mit den Rechten des ersten Verfassungszusatzes f\xfchren, und Eltern m\xfcssen m\xf6glicherweise auf die physische Entfernung von Bildschirmen zur\xfcckgreifen. Der Schutz von Kindern im Internet ist eine politische und kulturelle Debatte, die wenig Vertrauen in die F\xe4higkeit der Regierung l\xe4sst, Unternehmen der sozialen Medien zu regulieren."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nEin Artikel pl\xe4diert f\xfcr ein Verbot sozialer Medien f\xfcr unter 18-J\xe4hrige aufgrund der potenziellen drogen\xe4hnlichen Abh\xe4ngigkeit; die Regulierung solcher Inhalte stellt ein Problem dar. Eine Debatte \xfcber die Definition und den Einfluss von an Kinder gerichteter Werbung wirft Bedenken hinsichtlich der Regulierung von Werbung auf. Die sch\xe4dlichen Auswirkungen sozialer Medien auf die psychische Gesundheit und die pers\xf6nliche Entwicklung werden angesprochen, was zu Vorschl\xe4gen f\xfcr ein Verbot sozialer Medien von Unternehmen und algorithmischer Feeds f\xfchrt. Ein pauschales Verbot sozialer Medien wird nicht als L\xf6sung angesehen; es sind nuancierte Ans\xe4tze erforderlich. Discussion Service-Nutzer diskutieren \xfcber wirksame M\xf6glichkeiten zur Begrenzung der Bildschirmzeit und zur Bek\xe4mpfung negativer Auswirkungen. In der Debatte geht es darum, ein Gleichgewicht zwischen individueller Freiheit und gesellschaftlicher Verantwortung zu finden. Bedenken \xfcber die Kontrolle der sozialen Medien und die Dopaminaussch\xfcttung im Gehirn f\xfchren zu Diskussionen \xfcber ein Verbot von Algorithmen in den sozialen Medien. Die Durchf\xfchrbarkeit und der potenzielle Eingriff in die Privatsph\xe4re werden als Bedenken gegen\xfcber obligatorischen ID-Kontrollen f\xfcr Social-Media-Konten hervorgehoben. Es wird keine neue Technologie oder gr\xf6\xdfere Ver\xf6ffentlichung diskutiert."]}),"\n",(0,t.jsx)(n.h2,{id:"dang-wird-bald-65535-karmapunkte-haben",children:"Dang wird bald 65.535 Karmapunkte haben"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nDiscussion Service-Benutzer 'dang' wird voraussichtlich bald 65.535 Karmapunkte erreichen, was aufgrund der Verwendung einer vorzeichenbehafteten 16-Bit-Ganzzahl im System die maximale Grenze darstellt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, alias Dang, erreicht in K\xfcrze 65.535 Karmapunkte. Der Kommentarbereich ist voll von Lob f\xfcr Dangs Arbeit. Benutzer spekulieren, ob Karma umkippen wird und diskutieren den Wechsel zu 32-bit int. Moderationsstil und die Beteiligung von Y Combinator werden in Frage gestellt. Das Erreichen eines hohen Karmawertes wird als eine M\xf6glichkeit gesehen, Dangs Arbeit zu w\xfcrdigen. Das Erreichen h\xf6herer Karma-Meilensteine erm\xf6glicht zus\xe4tzliche F\xe4higkeiten auf Discussion Service, wie Upvoting/Downvoting."]}),"\n",(0,t.jsx)(n.h2,{id:"neuronale-netze-von-null-auf-held",children:"Neuronale Netze: Von Null auf Held"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nDer Kurs "Neuronale Netze: Zero to Hero" von Andrej Karpathy lehrt den Aufbau neuronaler Netze von Grund auf in Code. Der Kurs beginnt mit den Grundlagen der Backpropagation und geht weiter zu modernen tiefen neuronalen Netzen wie GPT. Der Kurs konzentriert sich auf Sprachmodelle, da diese ein ausgezeichneter Ort sind, um Deep Learning zu lernen. Zu den Voraussetzungen geh\xf6ren solide Programmierkenntnisse und mathematische Grundkenntnisse. Der Kurs beinhaltet das Erstellen von micrograd, makemore, einem MLP und das Eintauchen in einige der Interna von MLPs. Ein Backprop-Ninja zu werden und WaveNet zu erstellen wird ebenfalls behandelt. Der Kurs gipfelt in der Erstellung von GPT. In den Videos wird Schritt f\xfcr Schritt erkl\xe4rt, wie neuronale Netze optimiert werden, und der Schwerpunkt liegt auf dem Aufbau von Kompetenz und Intuition. Der Kurs empfiehlt den Zuschauern, die fr\xfcheren makemore-Videos anzusehen, um mit dem autoregressiven Sprachmodellierungsrahmen und den Grundlagen von Tensoren und PyTorch nn vertraut zu sein.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),'.\nAndrej Karpathys Kurs "Neuronale Netze: Zero to Hero"-Kurs erh\xe4lt \xfcber 300 Punkte auf Hacker News in 6 Stunden. Discussion Service-Benutzer loben seinen Lehrstil und empfehlen, nach dem Anschauen der Videos mitzucodieren. Sein von Gleichgesinnten geleiteter ML-Kurs erh\xe4lt positives Feedback, obwohl er ihn nicht erw\xe4hnt. Die Python-spezifische Syntax in den Videos k\xf6nnte f\xfcr einige Benutzer eine Herausforderung darstellen. In einer Diskussion wird der Schwerpunkt des Kurses auf logistische Regression und Perceptron bewertet. Die Teilnehmer fanden den Kurs einfach zu verstehen und empfehlen andere Kurse f\xfcr Anf\xe4nger. Einige Benutzer stellen die Mindestkenntnisse von Webentwicklern in Frage, und ein Benutzer hat eine Theorie \xfcber die Verbindung zwischen ML und Hopf-Algebra.']}),"\n",(0,t.jsx)(n.h2,{id:"ein-trick-um-den-fluss-zu-erreichen-lassen-sie-ihre-arbeit-kaputt-gehen",children:"Ein Trick, um den Fluss zu erreichen: Lassen Sie Ihre Arbeit kaputt gehen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nIn dem Artikel wird die Schwierigkeit er\xf6rtert, bei technischen Aufgaben in einen "Flow"-Zustand zu gelangen, und es wird ein Trick vorgestellt, wie man wieder in den Flow kommt. Der Autor schl\xe4gt vor, die eigene Arbeit in einem Zustand zu belassen, der offensichtlich defekt, aber leicht zu beheben ist, bevor man sich zur\xfcckzieht. Dies erm\xf6glicht einen klaren Ausgangspunkt f\xfcr die R\xfcckkehr zur Arbeit und schafft Schwung und Zuversicht. Der Artikel r\xe4umt ein, dass dieser Ansatz m\xf6glicherweise nicht universell oder in Teamkontexten anwendbar ist, bittet aber um Feedback f\xfcr andere Tricks. Es wird auch kurz auf Census Engineering und Besch\xe4ftigungsm\xf6glichkeiten eingegangen.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nDiscussion Service-Benutzer geben Tipps, wie man den Flow-Zustand erreicht, indem man die Arbeit unerledigt l\xe4sst, einschlie\xdflich der Methode "Parken mit Blick nach unten". Ein technischer Direktor f\xfchrte die Methode ein, die Arbeit bis 18 Uhr zu beenden, um Burnout zu vermeiden, beendete sie jedoch aufgrund von Pr\xe4sentismus. Die Benutzer diskutieren die Vorteile und Risiken strenger Zeitvorgaben und einer ver\xe4nderten Arbeitskultur. Einige geben Produktivit\xe4tstipps wie das Aufschreiben der n\xe4chsten Schritte und die Anwendung von TDD. Code in einem "kaputten" Zustand zu lassen, kann bei der sp\xe4teren Wiederaufnahme helfen, hat aber gemischte Ergebnisse.']}),"\n",(0,t.jsx)(n.h2,{id:"wird-der-arbeitsspeicher-vor-der-verwendung-in-einem-anderen-lxc-container-geleert",children:"Wird der Arbeitsspeicher vor der Verwendung in einem anderen LXC-Container geleert?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nEin Beitrag auf Information Security Stack Exchange fragt, ob RAM vor der Verwendung in einem anderen LXC-Container gel\xf6scht wird, was zu einer Diskussion \xfcber RAM-overprovisioning in LXC f\xfchrt, wobei ein Benutzer anmerkt, dass Speicher, der einem vorherigen Prozess in einem Container zugewiesen wurde, gel\xf6scht wird. Ein Beitrag auf Hacker News geht noch weiter und diskutiert gemeinsam genutzte Bibliotheken und den Schutz von Benutzer-Namensr\xe4umen. In einer Antwort wird klargestellt, dass Seiten vor der Zuweisung gel\xf6scht werden, dass Over-Provisioning keine gemeinsame Nutzung verursacht und dass LXC-Speicher Prozessen \xfcber Namensr\xe4ume zugewiesen wird, aber Prozesse von Host-Ressourcen getrennt sind. Schlie\xdflich wird darauf hingewiesen, dass die glibc-basierte Speicherverwaltung keine Aufr\xe4umarbeiten beinhaltet und freie Seiten Daten enthalten k\xf6nnen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nBenutzer auf Hacker News diskutierten \xfcber die Effektivit\xe4t und Notwendigkeit der automatischen Speicherbereinigung in Linux, wobei einige alternative Methoden zum L\xf6schen von ungenutztem Speicher vorschlugen. Ein Benutzer wies darauf hin, dass das Problem im Design des fork()-Systemaufrufs von UNIX liegt und viele speicherintensive Software immer noch mit OOM-Problemen zu k\xe4mpfen hat. Andere Kommentare er\xf6rtern die Unterschiede zwischen Overcommit- und Non-Overcommit-Speicherzuweisung in Linux und die Bedeutung der Festlegung von Grenzen. Der Artikel bietet eine differenzierte Sichtweise auf die Linux-Speicherzuweisung und richtet sich an Experten auf diesem Gebiet."]}),"\n",(0,t.jsx)(n.h2,{id:"perspektive-open-source-webassembly-gest\xfctzte-bi",children:"Perspektive: Open Source WebAssembly-gest\xfctzte BI"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective ist eine interaktive Analyse- und Datenvisualisierungskomponente, die f\xfcr Streaming und gro\xdfe Datenmengen mit konfigurierbaren Berichten, Dashboards und Notebooks entwickelt wurde. Sie verf\xfcgt \xfcber eine speichereffiziente Streaming-Abfrage-Engine in C++ und Python und eine Benutzeroberfl\xe4che, die als benutzerdefiniertes Element mit WebAssembly oder WebSocket verpackt ist. Die Benutzeroberfl\xe4che umfasst interaktive Dashboards, die in jedes Webanwendungs-Framework integriert werden k\xf6nnen. Perspective.js setzt auf WebAssembly und Apache Arrow f\xfcr eine desktop\xe4hnliche Leistung im Browser. PerspectivePython implementiert die Perspective API direkt in Python f\xfcr Forschung und Produktion. Es gibt virtualisierte und skalierbare Widgets, und das Projekt ist auf GitHub mit Benutzer- und Programmiererhandb\xfcchern verf\xfcgbar."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nDas Open-Source-WebAssembly-basierte BI-Tool Perspective wird trotz Leistungsproblemen f\xfcr seine leistungsstarke Funktionalit\xe4t gelobt: Als L\xf6sung wird unter anderem die Verwendung einer schlankeren Option vorgeschlagen. Die Macher von Perspective arbeiten an der Verbesserung der Leistung und der mobilen Kompatibilit\xe4t. Es wurden einige Bedenken hinsichtlich der Unterst\xfctzung von Firefox und der Zug\xe4nglichkeit bzw. des nicht-tastaturfreundlichen Designs ge\xe4u\xdfert. Die Einschr\xe4nkungen von Sciter wurden diskutiert, die Tauri-Bibliotheken als potentiell n\xfctzlich angesehen. Leistungsverbesserungen f\xfcr das Perspective-Projekt erforderlich."]}),"\n",(0,t.jsx)(n.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nAlexander Millers "Grid World" erforscht die Rolle von Gittern in seinem Leben von der Kindheit bis zum Erwachsenenalter, einschlie\xdflich ihrer Auswirkungen auf Technologie, Kunst und Navigation. Der Artikel befasst sich mit der Macht des Gitters bei der Kartierung und Kontrolle des Raums, wie sie in Spielen wie Battleship und Chess zum Ausdruck kommt. Das Raster wird zu einem zentralen Knotenpunkt, der Millers pers\xf6nliche Erfahrungen miteinander verbindet und zeigt, wie es zu einem Teil unseres Lebens wird. Miller schuf das Raster f\xfcr The HTML Review im Jahr 2023.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nDiscussion Service-Nutzer sind fasziniert von der au\xdfergew\xf6hnlichen Beherrschung und Kunstfertigkeit der Grid World in Webdesign und -entwicklung und ihrer Auswirkung auf die Wahrnehmung. Der Artikel erforscht die Unterstruktur des Gitters f\xfcr unsere Erinnerungen und die Welt, mit begleitenden Pixelgrafiken. In den Kommentaren wird die Verbindung zu den Neurowissenschaften mit den Rasterzellen hervorgehoben, w\xe4hrend gleichzeitig Kritik an der Rationalisierung und der \xdcberlagerung des Rasters durch die Natur ge\xe4u\xdfert wird. Ein Benutzer findet es schwierig, die visuellen Designaspekte seines pers\xf6nlichen Projekts zu perfektionieren. Nutzer diskutieren \xfcber die Rastermuster von Queens und die Geschichte hinter den Rastermustern. Ein Discussion Service-Nutzer gibt Einblicke in die Konformit\xe4t des NYC-Stra\xdfenrasters. Eine tisch\xe4hnliche Dekoration erzeugt schummrig beleuchtete Messehallen, w\xe4hrend sie sich im Laufe der Zeit entwickelt. Sie wurde mit einfachem Javascript ohne Bibliotheken erstellt und dient als technische \xdcbung."]}),"\n",(0,t.jsx)(n.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nDie OpenAI API ist eine Technologie, f\xfcr die JavaScript aktiviert sein muss."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI hat einen neuen Tokenizer ver\xf6ffentlicht, um GPT-Modelle besser zu verstehen. Der Tokenizer teilt den Text in Unterworteinheiten auf, um ihn effizienter verarbeiten zu k\xf6nnen, aber es fehlt ihnen an inh\xe4renter Bedeutung. Discussion Service-Benutzer diskutieren die Einschr\xe4nkungen des Tools, wie z. B. die Gruppierung auf der Grundlage von Leerzeichen und Gro\xdfbuchstabenbehandlung. Kodierungen, die mit Byte-Paar-Kodierung erstellt werden, sind oft nicht gut f\xfcr unterrepr\xe4sentierte Sprachen geeignet. OpenAI rechnet pro Token ab, da das Modell auf Token-Basis arbeitet."]}),"\n",(0,t.jsx)(n.h2,{id:"tabloid---die-clickbait-schlagzeilen-programmiersprache",children:"Tabloid - Die Clickbait-Schlagzeilen-Programmiersprache"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid ist eine neue Programmiersprache, die entwickelt wurde, um l\xe4cherliche und klickw\xfcrdige Schlagzeilen zu generieren, die denen in Boulevardzeitungen \xe4hneln. Die Sprache verwendet eine Kombination aus nat\xfcrlicher Sprachverarbeitung, maschinellem Lernen und Crowd-Sourcing, um Schlagzeilen mit klickw\xfcrdigen sprachlichen Mustern zu erstellen. Es ist eine lustige und unterhaltsame Sprache, die keinem eigentlichen Zweck dient, aber ein hervorragendes Beispiel daf\xfcr ist, wie Programmierung sowohl n\xfctzlich als auch am\xfcsant sein kann. Der Sch\xf6pfer von Tabloid plant, damit eine Plattform zu schaffen, auf der jeder seine Clickbait-Schlagzeilen erstellen kann. Discussion Service-NutzerInnen finden dieses Tool interessant und n\xfctzlich, um die Verarbeitung nat\xfcrlicher Sprache zu verstehen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nEin neues Projekt auf Hacker News namens Tabloid - The Clickbait Headline Programming Language. Das Projekt ist faszinierend, geschrieben von einem Autor, der behauptet, andere Sprachen geschrieben zu haben, die wohl noch n\xfctzlicher sind. Ein Discussion Service-Benutzer hat ein Programm in Tabloid gepostet, das f\xfcnf Zahlen nimmt und das Produkt der ersten drei Zahlen plus das Produkt der letzten beiden zur\xfcckgibt. Der Autor ist jemand, der viele interessante Projekte ver\xf6ffentlicht hat und Oak unter anderem auch zum Aufbau einer pers\xf6nlichen Software-Infrastruktur verwendet. Ein anderer Discussion Service-Benutzer merkte an, dass es f\xfcr einzelne Entwickler am praktikabelsten ist, alles von Grund auf neu zu schreiben, aber nicht f\xfcr Teams, wo es besser ist, mit "langweilig" zu arbeiten.']}),"\n",(0,t.jsx)(n.h2,{id:"gpt4-simuliert-einen-ftp-server-auf-ftpdisneycom",children:"GPT4 simuliert einen FTP-Server auf ftp.disney.com"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nDer Chat GPT-4 simuliert einen FTP-Server f\xfcr Disney, indem er das Basis-Tool ftp cli verwendet und die Befehle wie ein echter Benutzer ausf\xfchrt. Der simulierte Server enth\xe4lt exklusive Disney-Inhalte in Ordnern wie Filmen, Soundtracks und Hintergrundbildern, und GPT-4 erweist sich als f\xe4hig, in lokalen und entfernten Dateisystemen zu navigieren. Die Leistung der neuen Technologie \xfcbertrifft die Erwartungen und zeigt, dass sie in der Lage ist, \xfcberzeugende Inhalte f\xfcr Disney-Fans zu erstellen. Der Artikel weist auf zuk\xfcnftige Anwendungen f\xfcr GPT-4 in Code-Interpreter-Plugins hin, die den Zugriff auf erfundene Server von FTP-Clients aus erm\xf6glichen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nEin Artikel auf Hacker News diskutiert, wie GPT4 einen FTP-Server auf ftp.disney.com simuliert. Die Benutzer diskutieren dar\xfcber, ob dies als "Halluzination" betrachtet werden kann oder nicht, trotz des Potenzials f\xfcr KI, zu simulieren oder zu "halluzinieren". Die Genauigkeit der von der KI erzeugten Antworten und die Wahrnehmung dieser Ergebnisse als "Halluzinationen" sind ebenfalls Diskussionspunkte. Weitere Themen sind: die M\xf6glichkeit, dass selbst erstellte Filme oder Fernsehsendungen wertlos sind, die Rolle des latenten Raums und der Sprache in LLMs, die Auswirkungen der Technologie auf die Gesellschaft und die Grenzen der derzeitigen KI-F\xe4higkeiten. Einige Nutzer warnen davor, die F\xe4higkeiten der KI \xfcberzubewerten, und merken an, dass ihre Grenzen oft \xfcbersehen werden.']}),"\n",(0,t.jsx)(n.h2,{id:"mmap-verwenden-um-llama-schneller-laden-zu-lassen",children:"mmap verwenden, um LLaMA schneller laden zu lassen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA verwendet mmap(), um Modelle 100x schneller zu laden, erh\xf6ht die RAM-Stabilit\xe4t und erm\xf6glicht die gleichzeitige Ausf\xfchrung mehrerer Prozesse. Linux-Benutzer erhalten eine 100-fache Verbesserung, w\xe4hrend Windows und MacOS eine 10-fache erhalten. Der neue mmap()-Lader ist jetzt auf GitHub unter MIT-Lizenz verf\xfcgbar. Der anonyme Mitarbeiter @Slaren f\xfcgte LLaMA-7B die mmap()-Unterst\xfctzung hinzu, die sofortige Ladezeiten ohne \xc4nderung des Dateiformats erm\xf6glicht. Das neue Dateiformat richtet die Tensoren an einer 32-Byte-Grenze aus. Der Beitrag untersucht potenzielle Verbesserungen bei der Festplattennutzung und Leistungsunterbrechungen. Justine Tunney schreibt \xfcber Twitter und Github in Standard-Utilities, die sich an Experten auf diesem Gebiet richten. Er ist klar und pr\xe4gnant, ohne Voreingenommenheit oder politische oder religi\xf6se Aussagen. Ein Discussion Service-Nutzer kommentiert, dass Tunneys Beitrag eine gro\xdfartige Ressource zum Lernen ist."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nDie Verwendung von mmap, um LLaMA schneller laden zu lassen, ist der Hauptfokus des Artikels, trotz des Dramas um die Zuschreibung und technische Probleme im Kommentarbereich. Die Vor- und Nachteile von mmap werden diskutiert, ebenso wie die technischen Vorz\xfcge von Facebooks LLaMA.cpp. Die Nutzer diskutieren den Nutzen der LLaMA-\xc4nderungen und die Vor- und Nachteile verschiedener Funktionen und bieten wertvolle Einblicke f\xfcr technisch versierte Leser, die mehr \xfcber KI und die Implementierung von Modellen erfahren m\xf6chten. Der Beitrag beleuchtet eine systemtechnische Herangehensweise an ein Problem und einen Trend zu propriet\xe4rem Code in Bibliotheken, der eine Diskussion \xfcber die Verwendung von Huge Pages und die Schwierigkeit, IO-Engp\xe4sse zu l\xf6sen, ausl\xf6st. Die revolution\xe4re Leistungsverbesserung durch mmap hat die Aufmerksamkeit von Experten auf diesem Gebiet geweckt."]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}}}]);